import{_ as i,c as a,o as t,ag as n}from"./chunks/framework.DfL_BkQ-.js";const h=JSON.parse('{"title":"Extension de synchronisation Finder","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/finder-sync.md","filePath":"fr/guide/finder-sync.md","lastUpdated":1794112334000}'),s={name:"fr/guide/finder-sync.md"};function o(l,e,r,d,c,u){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="extension-de-synchronisation-finder" tabindex="-1">Extension de synchronisation Finder <a class="header-anchor" href="#extension-de-synchronisation-finder" aria-label="Permalink to &quot;Extension de synchronisation Finder&quot;">​</a></h1><h2 id="presentation" tabindex="-1">Présentation <a class="header-anchor" href="#presentation" aria-label="Permalink to &quot;Présentation&quot;">​</a></h2><p>L&#39;extension de synchronisation Nicasa Finder ajoute un bouton dans la barre d&#39;outils du Finder de macOS, vous permettant de traiter rapidement vos fichiers image sans ouvrir l&#39;application principale Nicasa.</p><h3 id="fonctionnalites" tabindex="-1">Fonctionnalités <a class="header-anchor" href="#fonctionnalites" aria-label="Permalink to &quot;Fonctionnalités&quot;">​</a></h3><ul><li><strong>Optimiseur d&#39;images</strong> : compresse et optimise les images sélectionnées</li><li><strong>Éditeur d&#39;images par IA</strong> : édite les images sélectionnées avec l&#39;IA (réparation, amélioration, remplissage, etc.)</li><li><strong>Accès rapide depuis la barre d&#39;outils du Finder</strong></li><li><strong>Fonctionne avec plusieurs images sélectionnées</strong></li></ul><h2 id="installation-et-configuration" tabindex="-1">Installation et configuration <a class="header-anchor" href="#installation-et-configuration" aria-label="Permalink to &quot;Installation et configuration&quot;">​</a></h2><h3 id="installation-via-l-application-nicasa" tabindex="-1">Installation via l&#39;application Nicasa <a class="header-anchor" href="#installation-via-l-application-nicasa" aria-label="Permalink to &quot;Installation via l&#39;application Nicasa&quot;">​</a></h3><p>L&#39;extension de synchronisation est incluse avec l&#39;application principale Nicasa. Après avoir installé l&#39;application, activez l&#39;extension :</p><ol><li>Ouvrez <strong>Réglages Système</strong> &gt; <strong>Extensions</strong> &gt; <strong>Extensions du Finder</strong></li><li>Activez <strong>Nicasa Finder Sync</strong></li></ol><h3 id="bouton-de-la-barre-d-outils" tabindex="-1">Bouton de la barre d&#39;outils <a class="header-anchor" href="#bouton-de-la-barre-d-outils" aria-label="Permalink to &quot;Bouton de la barre d&#39;outils&quot;">​</a></h3><p>Une fois activée, une icône Nicasa apparaît dans la barre d&#39;outils du Finder.</p><p>Si elle n&#39;est pas visible :</p><ol><li>Faites un clic droit sur la barre d&#39;outils du Finder</li><li>Sélectionnez <strong>Personnaliser la barre d&#39;outils…</strong></li><li>Faites glisser le bouton Nicasa à l&#39;emplacement voulu</li></ol><h2 id="utiliser-le-bouton-de-la-barre-d-outils-du-finder" tabindex="-1">Utiliser le bouton de la barre d&#39;outils du Finder <a class="header-anchor" href="#utiliser-le-bouton-de-la-barre-d-outils-du-finder" aria-label="Permalink to &quot;Utiliser le bouton de la barre d&#39;outils du Finder&quot;">​</a></h2><h3 id="selectionner-des-fichiers" tabindex="-1">Sélectionner des fichiers <a class="header-anchor" href="#selectionner-des-fichiers" aria-label="Permalink to &quot;Sélectionner des fichiers&quot;">​</a></h3><p>Ouvrez le Finder et sélectionnez une ou plusieurs images. Formats pris en charge :</p><ul><li><code>.jpg</code>, <code>.jpeg</code>, <code>.png</code>, <code>.gif</code>, <code>.bmp</code>, <code>.webp</code>, <code>.svg</code>, <code>.tiff</code>, <code>.ico</code></li></ul><h3 id="utiliser-le-menu" tabindex="-1">Utiliser le menu <a class="header-anchor" href="#utiliser-le-menu" aria-label="Permalink to &quot;Utiliser le menu&quot;">​</a></h3><p>Cliquez sur le bouton Nicasa de la barre d&#39;outils, puis choisissez :</p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>Optimiseur d&#39;images</strong></td><td>Compresse et optimise les images sélectionnées</td></tr><tr><td><strong>Éditeur d&#39;images par IA</strong></td><td>Ouvre les images sélectionnées dans l&#39;éditeur IA de Nicasa pour les réparer, les améliorer ou les retoucher</td></tr></tbody></table><blockquote><p>⚠️ <strong>Remarque</strong> : si aucun fichier n&#39;est sélectionné, le bouton émet un bip et l&#39;action ne s&#39;exécute pas.</p></blockquote><h3 id="flux-de-travail" tabindex="-1">Flux de travail <a class="header-anchor" href="#flux-de-travail" aria-label="Permalink to &quot;Flux de travail&quot;">​</a></h3><ol><li>Sélectionnez des images dans le Finder</li><li>Cliquez sur le bouton Nicasa de la barre d&#39;outils → choisissez l&#39;action souhaitée</li><li>L&#39;application Nicasa s&#39;ouvre automatiquement et traite les images sélectionnées</li></ol><h2 id="conseils" tabindex="-1">Conseils <a class="header-anchor" href="#conseils" aria-label="Permalink to &quot;Conseils&quot;">​</a></h2><ul><li>Pour de meilleurs résultats, sélectionnez des images dans un dossier auquel vous avez accès</li><li>Vous pouvez sélectionner plusieurs fichiers à la fois</li><li>Si une image ne s&#39;ouvre pas, vérifiez qu&#39;elle fait partie des formats pris en charge</li><li>L&#39;extension s&#39;intègre parfaitement au bac à sable de macOS : vous ne devez autoriser l&#39;accès qu&#39;une seule fois</li></ul>',25)])])}const m=i(s,[["render",o]]);export{h as __pageData,m as default};
